import functools
import hashlib

def memoize(ttl=300):
    def decorator(func):
        cache = {}
        def wrapper(*args, **kwargs):
            key = hashlib.md5(str(args).encode()).hexdigest()
            if key in cache:
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            return result
        return wrapper
    return decorator

